<a href="<?=e(url('/admin/documents'))?>">&larr; Document queue</a><h1 class="h2 my-3"><?=e($document['document_reference'])?></h1><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body"><h2 class="h4">Private document</h2><dl class="row"><dt class="col-sm-4">Member</dt><dd class="col-sm-8"><?=e($document['name'])?> | <?=e($document['email'])?></dd><dt class="col-sm-4">Application</dt><dd class="col-sm-8"><?=e($document['application_number'])?></dd><dt class="col-sm-4">Type / file</dt><dd class="col-sm-8"><?=e($document['document_type_name'])?> | <?=e($document['original_filename'])?></dd><dt class="col-sm-4">MIME / size</dt><dd class="col-sm-8"><?=e($document['detected_mime'])?> | <?=e(number_format($document['byte_size']/1024,1))?> KB</dd><dt class="col-sm-4">SHA-256</dt><dd class="col-sm-8 text-break"><code><?=e($document['sha256'])?></code></dd><dt class="col-sm-4">Status</dt><dd class="col-sm-8"><?=e(ucfirst($document['verification_status']))?></dd></dl><a class="btn btn-outline-primary" href="<?=e(url('/admin/documents/'.$document['document_reference'].'/download'))?>">Secure download</a><?php if($document['rejection_reason']):?><div class="alert alert-danger mt-3"><?=e($document['rejection_reason'])?></div><?php endif;?><?php if($document['internal_note']):?><div class="alert alert-secondary"><?=e($document['internal_note'])?></div><?php endif;?></div></div><div class="card mt-4"><div class="card-body"><h2 class="h4">Timeline</h2><ul class="list-group"><?php foreach($events as $event):?><li class="list-group-item"><strong><?=e(ucfirst($event['new_status']))?></strong> | <?=e(date('j M Y, H:i',strtotime($event['created_at'])))?><?php if($event['note']):?><div><?=e($event['note'])?></div><?php endif;?></li><?php endforeach;?></ul></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h5">Verification</h2><?php if($document['verification_status']==='pending'):?><form method="post" action="<?=e(url('/admin/documents/'.$document['document_reference'].'/verify'))?>"><?=csrf_field()?><label for="verify_note">Private note</label><textarea class="form-control mb-2" id="verify_note" name="internal_note" maxlength="2000"></textarea><button class="btn btn-success w-100">Verify</button></form><hr><form method="post" action="<?=e(url('/admin/documents/'.$document['document_reference'].'/reject'))?>"><?=csrf_field()?><label for="reason">Applicant-visible reason</label><textarea class="form-control mb-2" id="reason" name="rejection_reason" maxlength="1000" required></textarea><label for="internal">Private note</label><textarea class="form-control mb-2" id="internal" name="internal_note" maxlength="2000"></textarea><button class="btn btn-danger w-100">Reject</button></form><?php else:?><p>No verification transition is available.</p><?php endif;?></div></div></div></div>
